/* ===== مزامنة الخادم: المنتجات والإعدادات تُحفظ على الخادم وتظهر لكل الزوار ===== */
var SRVOK=false,remoteReady=false,remoteEmpty=false,pushT,lastPushed='';
async function pullRemote(){
  try{
    const r=await fetch(location.origin+'/catalog',{cache:'no-store'});
    const j=await r.json();
    if(!j||j.srv!==true)return;
    SRVOK=true;remoteEmpty=!j.data;remoteReady=true;try{if(!sessionStorage.lcv2&&!/^#admin/.test(location.hash)){sessionStorage.lcv2=1;fetch('/visit',{method:'POST',body:'{}',keepalive:true}).catch(()=>{})}}catch(e){}
    if(j.data){
      const keep={O:S.O,sq:S.sq,vis:S.vis,seq:S.seq,pw:S.pw,tk:S.tk,tid:S.tid,tp:S.tp};
      S={...D,...j.data,...keep};
      try{localStorage.lc=JSON.stringify(S)}catch(e){}
      lastPushed=JSON.stringify(pubData());
      setLang(lang);
    }
  }catch(e){}
}
function pubData(){const d={...S};delete d.O;delete d.vis;delete d.sq;return d}
function pushRemote(){
  if(!SRVOK||!remoteReady||!gtok())return;
  clearTimeout(pushT);
  pushT=setTimeout(async()=>{
    try{
      const js=JSON.stringify(pubData());if(js===lastPushed)return;
      const r=await fetch(API()+'/settings',{method:'POST',headers:{'Content-Type':'application/json',...authH()},body:JSON.stringify({data:pubData()})});
      if(r.status==401)toast('انتهت الجلسة: سجّل الدخول من جديد ليُحفظ التغيير للجميع');
      else if(!r.ok)toast('تعذر حفظ التغييرات على الخادم');
      else{lastPushed=js;remoteEmpty=false;toast('تم الحفظ وسيظهر للجميع')}
    }catch(e){toast('تعذر حفظ التغييرات على الخادم')}
  },700);
}
pullRemote();

