function c10Begin(v){pend=v;ff={name:v.name,ph:v.ph,ci:v.ci,ae:v.ae,lm:v.lm};c10n=10;view='c10';rc();clearInterval(c10t);c10t=setInterval(()=>{c10n--;const e=$('#c10n');if(e)e.textContent=c10n;if(c10n<=0)c10Go()},1000)}
