/* ===== تتبع الطلب بخطوات + إلغاء خلال 10 دقائق ===== */
var ORD_STEPS=['Order received','Order confirmed','Order shipped','On its way to you','Order delivered'];
var trk={},trkTick=0,trkSel='',trkCode='',trkPh='',trkOff=0,trkN=0;
const mmss=ms=>{const s=Math.ceil(ms/1000);return Math.floor(s/60)+':'+String(s%60).padStart(2,'0')};
function rememberOrder(o){try{const a=JSON.parse(localStorage.lco||'[]').filter(x=>x.code!==o.code);a.unshift({code:o.code,ph:o.ph});localStorage.lco=JSON.stringify(a.slice(0,20))}catch(e){}}
function knownPh(code){try{return(JSON.parse(localStorage.lco||'[]').find(x=>x.code===code)||{}).ph||''}catch(e){return''}}
function trkHTML(r,ph){
  if(r.s==null)return `<p class="em">${tx('Order not found. Check the code.')}</p>`;
  const cancelled=r.s===0,left=Math.max(0,(r.cancelUntil||0)-(Date.now()+trkOff));
  const steps=ORD_STEPS.map((x,i)=>{const n=i+1,done=!cancelled&&r.s>n,cur=!cancelled&&r.s===n,ev=(r.events||[]).find(e=>e.s===n);
    return `<li class="${done?'done':cur?'cur':''}"><i>${done?'✓':n}</i><span><b>${tx(x)}</b>${ev?`<small>${new Date(ev.at).toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'})}</small>`:''}</span></li>`}).join('');
  let foot='';
  if(cancelled)foot=`<p class="er2">${tx('Your order has been cancelled.')}</p>`;
  else if(r.s===1&&left>0)foot=`<p class="cw">${tx('You can cancel your order for')} <b class="cwt">${mmss(left)}</b></p>${ph?`<button class="btn g" data-a="ocx" data-c="${esc(r.code||trkCode)}">${tx('Cancel order')}</button>`:''}`;
  return `<div class="tlw"><p class="tlc">${tx('Order code')} <b>${esc(r.code||trkCode)}</b></p>${cancelled?'':`<ol class="tl">${steps}</ol>`}${foot}</div>`}
function trkMount(code,ph,sel){trkCode=code;trkPh=ph||knownPh(code);trkSel=sel;trkN=0;trk={};trkRefresh();clearInterval(trkTick);trkTick=setInterval(trkLoop,1000)}
async function trkRefresh(){try{const r=await fetch(API()+'/track?code='+encodeURIComponent(trkCode),{cache:'no-store'});const j=await r.json();j.code=j.code||trkCode;trkOff=j.now?j.now-Date.now():0;trk=j;const el=$(trkSel);if(el)el.innerHTML=trkHTML(trk,trkPh)}catch(e){const el=$(trkSel);if(el&&!el.innerHTML)el.textContent=tx('Tracking is not available right now.')}}
function trkLoop(){const el=$(trkSel);if(!el){clearInterval(trkTick);return}trkN++;
  if(trk.s===1){const left=Math.max(0,trk.cancelUntil-(Date.now()+trkOff)),t=el.querySelector('.cwt');if(t)t.textContent=mmss(left);if(left<=0&&!trk._exp){trk._exp=1;trkRefresh()}}
  if(trkN%15===0&&trk.s!==5&&trk.s!==0)trkRefresh()}
async function cancelOrder(code){
  if(!confirm(tx('Cancel this order?')))return;
  try{const r=await fetch(API()+'/order/cancel',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({code,ph:knownPh(code)||trkPh})});const j=await r.json();
    if(j.ok){toast('Your order has been cancelled.');trkRefresh()}else{toast(j.error||'Cancellation window ended.');trkRefresh()}}catch(e){toast('Tracking is not available right now.')}}

/* ===== لوحة الأدمن: إدارة الطلبات من الخادم ===== */
var ST_AR=['ملغى','تم الاستلام','تم التأكيد','تم الشحن','في الطريق','تم التوصيل'],orF='';
TB.or=()=>{setTimeout(loadOr,0);return `<p class="em">جارٍ تحميل الطلبات…</p><div id="orl"></div>`};
async function loadOr(){const el=$('#orl');if(!el)return;let list;
  try{list=((await apiJ('/orders')).orders||[]).slice().reverse()}catch(e){if(el.isConnected)el.innerHTML='<p class="em">تعذر تحميل الطلبات. تأكد من تسجيل الدخول ومن تشغيل الخادم.</p>';return}
  const oq=String(window.orQ||'').trim().toLowerCase(),shown=list.filter(o=>(orF===''||String(o.st)===String(orF))&&(!oq||[o.name,o.ph,o.code,o.ad,String(o.id)].some(x=>String(x||'').toLowerCase().includes(oq))));
  const sel=o=>`<select data-ost="${esc(o.code)}">${ST_AR.map((t,i)=>`<option value="${i}" ${o.st===i?'selected':''}>${t}</option>`).join('')}</select>`;
  el.innerHTML=`<div class="cd"><h3>الطلبات (${list.length})</h3><div class="chips">${[['','الكل'],[1,'جديدة'],[2,'مؤكدة'],[3,'مشحونة'],[4,'في الطريق'],[5,'مسلّمة'],[0,'ملغاة']].map(([v,l])=>`<button data-a="orf" data-c="${v}" class="${String(orF)===String(v)?'on':''}">${l}${v===''?'':` (${list.filter(o=>o.st===v).length})`}</button>`).join('')}</div>
  ${shown.map(o=>`<div class="cd" style="margin:8px 0"><div style="display:flex;justify-content:space-between;gap:8px;flex-wrap:wrap"><b>#${o.id} · ${esc(o.code)}</b><span>${new Date(o.d).toLocaleString('ar-IQ')}</span></div>
   <div>${esc(o.name)} · <a href="tel:${esc(o.ph)}">${esc(o.ph)}</a></div><div class="em" style="padding:2px 0">${esc(o.ad)}</div>
   <div>${o.items.map(i=>`${i.q}× ${esc(i.n)}${i.cc?` (${esc(i.cc)})`:''}`).join('، ')}</div>
   <div style="display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px"><b>${fm(o.t)}${o.dc?` <small>(${esc(o.dc)})</small>`:''}</b>${sel(o)}</div></div>`).join('')||'<p class="em">لا توجد طلبات.</p>'}</div>`}
Object.assign(A,{orf:c=>{orF=c;loadOr()}});
document.addEventListener('change',async e=>{const c=e.target.dataset&&e.target.dataset.ost;if(!c)return;
  try{const r=await apiJ('/status',{method:'POST',body:JSON.stringify({code:c,s:+e.target.value})});toast(r.ok?'تم تحديث حالة الطلب':'فشل التحديث')}catch(x){toast('فشل التحديث')}loadOr()});
setInterval(()=>{if(au&&at=='or'&&document.visibilityState=='visible'&&!document.activeElement?.dataset?.ost)loadOr()},20000);

addEventListener('change',e=>{const t=e.target;if(t&&t.name=='pay'&&t.closest('#of')){ff={...ff,...Object.fromEntries(new FormData($('#of')))};delete ff.pay;pay=t.value;QK='';rc()}});

function descHTML(p){const di=(p.di||[]).filter(d=>d&&d.u),paras=String(p.d||'').split(/\n+/).filter(Boolean),im=pos=>di.filter(d=>(d.pos||'start')==pos).map(d=>`<img class="di" loading="lazy" src="${esc(d.u)}" alt="" style="width:${Math.max(10,Math.min(100,+d.w||100))}%;${d.al=='left'?'margin:8px auto 8px 0':d.al=='right'?'margin:8px 0 8px auto':'margin:8px auto'}">`).join(''),h=Math.ceil(paras.length/2),ps=a=>a.map(x=>`<p>${esc(x)}</p>`).join('');return `<div class="dsc">${im('start')}${ps(paras.slice(0,h))}${im('mid')}${ps(paras.slice(h))}${im('end')}</div>`}
